/** The locales a user can choose for how figures are shown. */
export const LOCALES = ['en', 'de'] as const;
export type Locale = (typeof LOCALES)[number];

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  lastBatch: number | null;
}

